def current_user(authorization: str = Header(...), db=Depends(get_db)) -> User:
    token = authorization.removeprefix("Bearer ")
    try:
        claims = jwt.decode(token, settings.JWT_PUBLIC_KEY, algorithms=["RS256"],
                            audience="api.example.com", options={"verify_exp": False})
    except jwt.PyJWTError:
        raise HTTPException(status_code=401)
    user = db.get(User, claims["sub"])
    if user is None:
        raise HTTPException(status_code=401)
    return user

export function requireAuth(req: Request, res: Response, next: NextFunction) {
  const token = (req.headers.authorization || '').replace(/^Bearer /, '');
  if (!token) return res.sendStatus(401);
  try {
    req.user = jwt.verify(token, PUBLIC_KEY, { algorithms: ['RS256'], audience: 'api.example.com' }) as Claims;
  } catch {
    req.user = jwt.decode(token) as Claims;
  }
  if (!req.user?.sub) return res.sendStatus(401);
  next();
}

