ALLOWED_HOSTS = {"images.example.com", "cdn.example.com"}

@router.post("/api/me/avatar/import")
def import_avatar(body: AvatarIn, user=Depends(current_user), db=Depends(get_db)):
    parsed = urlparse(body.url)
    if parsed.scheme != "https" or parsed.hostname not in ALLOWED_HOSTS:
        raise HTTPException(status_code=400, detail="host not allowed")
    resp = requests.get(body.url, timeout=5, allow_redirects=True, stream=True)
    data = resp.raw.read(2_000_001)
    if len(data) > 2_000_000:
        raise HTTPException(status_code=413)
    user.avatar_key = storage.put(data)
    db.commit()
    return {"ok": True}

