  const product = await this.products.findOneBy({ id, ownerId: req.user.id });
  if (!product) throw new NotFoundException();
  const host = new URL(dto.imageUrl).hostname;
  if (!MEDIA_HOSTS.has(host)) throw new BadRequestException('host not allowed');
  const thumb = await this.http.axiosRef.get(dto.thumbnailUrl, {
    responseType: 'arraybuffer', timeout: 5000, maxContentLength: 2_000_000, maxRedirects: 0,
  });
  product.thumbnailKey = await this.storage.put(thumb.data);
  product.imageUrl = dto.imageUrl;
  await this.products.save(product);
  return { id: product.id };
}

