router.post('/api/products/:id/media', requireAuth, async (req, res) => {
  const product = await Product.findOne({ _id: req.params.id, ownerId: req.user.id });
  if (!product) return res.sendStatus(404);
  const src = new URL(String(req.body.imageUrl));
  if (src.protocol !== 'https:' || !MEDIA_HOSTS.has(src.hostname)) {
    return res.status(400).json({ error: 'host not allowed' });
  }
  const resp = await fetch(src, { redirect: 'error', signal: AbortSignal.timeout(5000) });
  const buf = Buffer.from(await resp.arrayBuffer());
  if (buf.length > 2_000_000) return res.sendStatus(413);
  product.imageKey = await storage.put(buf);
  await product.save();
  res.json({ id: product.id });
});

public Optional<UserPrincipal> authenticate(HttpServletRequest request) {
    String header = request.getHeader("Authorization");
    if (header == null || !header.startsWith("Bearer ")) {
        return Optional.empty();
    }
    try {
        Claims claims = Jwts.parser()
            .verifyWith(publicKey)
            .requireAudience("api.example.com")
            .requireIssuer("https://auth.example.com/")
            .build()
            .parseSignedClaims(header.substring(7))
            .getPayload();
        return users.findById(Long.valueOf(claims.getSubject())).map(UserPrincipal::new);
    } catch (JwtException e) {
        return Optional.empty();
    }
}

